# uniclubs_recovery_scenario.py
"""Exercise an offline UniClubs bundle and persisted plans across real process restarts.

Run only through ``python -m views.check_uniclubs_recovery`` so app files are disposable.
This reuses the existing real Streamlit handler helpers instead of reimplementing the UI.
"""
