from datetime import datetime
import json
import os

import activity_sources
import calendar_export
import config
import database
import ui_components
import uniclubs_database
import uniclubs_export
import uniclubs_user
from views import uniclubs_scenario


SOURCE_ID = uniclubs_scenario.SOURCE_ID
SERIES_ID = 'uniclubs-series:fixture-event'
CLUB_ID = 'uniclubs-club:fixture-club'
OLDER_SOURCE_TIME = '2026-11-02T09:00:00.000000Z'


class RecoveryScenario(uniclubs_scenario.UniClubsScenario):
    """Use the existing UI helpers with one persisted-data assertion phase per interpreter."""

    phase = 'seed'

    def setUp(self):
        """Install the existing isolated clocks and network guards, then choose a feed fault."""
        self.feed_calls = 0
        self.expected_file = config.PRIVATE_DIR / 'recovery_expected.json'
        if self.phase == 'seed':
            self.assertFalse(config.DB_FILE.exists())
            self.assertFalse(config.UNICLUBS_DB_FILE.exists())
            self.assertFalse(config.UNICLUBS_USER_DB_FILE.exists())
        super().setUp()
        self.download_error = self.phase in ('seed', 'offline')
        if self.phase == 'malformed':
            self.document['events'][0]['start_utc'] = 'not a source timestamp'
        elif self.phase == 'older':
            self.document['_meta']['last_success_utc'] = OLDER_SOURCE_TIME
            for event in self.document['events']:
                event['last_seen_utc'] = OLDER_SOURCE_TIME
            self.document['events'][0]['title'] = 'Old snapshot must not replace the saved title'
            uniclubs_export.validate_export(self.document)

    def update_document(self, updated):
        """Bundle a newer fixture only for cold start; subsequent processes read existing files."""
        if self.phase == 'seed':
            super().update_document(False)
            super().update_document(True)
        else:
            self.document = json.loads(config.UNICLUBS_EXPORT_FILE.read_text(encoding='utf-8'))

    def fetch_document(self):
        """Supply an explicit transport failure, malformed JSON object or valid older feed."""
        self.feed_calls += 1
        return super().fetch_document()

    def test_public_feed_calendar_roundtrip(self):
        """Override the original scenario with a cold-start or restart-specific UI assertion."""
        if self.phase == 'seed':
            self.seed_offline_plan()
        else:
            self.restore_offline_plan()
        self.assert_retained_state()

    def seed_offline_plan(self):
        """Cold start from bundled JSON while the live feed fails, then plan through the UI."""
        self.onboard()
        self.details()
        for key in ('ww_favorite_series_', 'ww_favorite_club_'):
            self.app.session_state['ww_open_event_id'] = SOURCE_ID
            self.app.checkbox(key=key + SOURCE_ID).check().run()
            self.clean()
        self.app.session_state['ww_open_event_id'] = SOURCE_ID
        self.app.button(key='ww_confirm_event').click().run()
        self.clean()
        event = activity_sources.load_event(SOURCE_ID)
        self.assertEqual(event.start, datetime(2026, 11, 3, 21))
        expected = {
            'pid': os.getpid(),
            'owner': activity_sources.profile_key(self.connection, self.user_id),
            'user_id': self.user_id, 'uid': calendar_export.make_uid(event),
            'catalog': self.catalog_document(),
            'interaction': activity_sources.get_interaction(
                self.connection, self.user_id, SOURCE_ID),
        }
        self.expected_file.write_text(json.dumps(expected, sort_keys=True), encoding='utf-8')

    def restore_offline_plan(self):
        """Start the real app with no prior session/cache and restore the same saved identity."""
        self.assertTrue(self.expected_file.exists())
        self.expected = json.loads(self.expected_file.read_text(encoding='utf-8'))
        self.assertNotEqual(os.getpid(), self.expected['pid'])
        self.new_session()
        self.connection = database.get_connection(config.DB_FILE)
        self.user_id = database.get_current_user_id(self.connection)
        self.assertEqual(self.user_id, self.expected['user_id'])
        self.assertEqual(activity_sources.profile_key(self.connection, self.user_id),
                         self.expected['owner'])
        self.assertFalse(any(button.key == 'ww_welcome_next' for button in self.app.button))
        self.details()
        self.assertIn((SOURCE_ID, False), self.exports)
        self.assertIn('UID:' + self.expected['uid'], self.exports[SOURCE_ID, False])

    def catalog_document(self):
        """Read only the validated public state, excluding local failed-check diagnostics."""
        catalog = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            return uniclubs_export.build_export(catalog)
        finally:
            catalog.close()

    def assert_integrity(self, connection):
        """Check SQLite structural and foreign-key integrity after each independent restart."""
        self.assertEqual(connection.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        self.assertEqual(connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def assert_retained_state(self):
        """Require last-good public data, private plan/favorites and separate legacy tables."""
        self.assertGreater(self.feed_calls, 0)
        expected = json.loads(self.expected_file.read_text(encoding='utf-8'))
        self.assertEqual(self.catalog_document(), expected['catalog'])
        status = ui_components.uniclubs_status()
        self.assertFalse(status['ok'])
        self.assertTrue(status['catalog_available'])
        self.assertEqual(status['source_success_utc'],
                         expected['catalog']['_meta']['last_success_utc'])
        if self.phase == 'older':
            self.assertIn('older than', status['message'])
        else:
            self.assertIn('keeping the last saved', status['message'])
        self.assertIn(status['message'], uniclubs_scenario.values(self.app.caption))
        interaction = activity_sources.get_interaction(self.connection, self.user_id, SOURCE_ID)
        self.assertEqual(interaction, expected['interaction'])
        self.assertEqual(interaction['status'], 'confirmed')
        profile = activity_sources.get_profile(self.connection, self.user_id)
        self.assertEqual(profile.display_name, 'Alex')
        self.assertIn(SERIES_ID, profile.favorite_series_ids)
        self.assertIn(CLUB_ID, profile.favorite_club_ids)
        self.assertTrue(any(button.key and button.key.startswith('ww_timeline_event_')
                            and button.key.endswith(SOURCE_ID) for button in self.app.button))
        legacy = self.connection.execute('SELECT count(*) FROM interactions WHERE event_id=?',
                                         (SOURCE_ID,)).fetchone()[0]
        self.assertEqual(legacy, 0)
        legacy = self.connection.execute('SELECT count(*) FROM series WHERE external_id=?',
                                         ('fixture-event',)).fetchone()[0]
        self.assertEqual(legacy, 0)
        self.assert_integrity(self.connection)
        for path, module in ((config.UNICLUBS_DB_FILE, uniclubs_database),
                             (config.UNICLUBS_USER_DB_FILE, uniclubs_user)):
            connection = module.get_connection(path)
            try:
                self.assert_integrity(connection)
            finally:
                connection.close()
